using namespace std;
using namespace lcd;

// Description of |3170. Lexicographically Minimum String After Removing Stars|:
//
// You are given a string |s|. It may contain any number of |'*'| characters.
// Your task is to remove all |'*'| characters. While there is a |'*'|, do the
// following operation:
//
//  • Delete the leftmost |'*'| and the smallest non- |'*'| character to its
//  left. If there are several smallest characters, you can delete any of them.
// Return the lexicographically smallest resulting string after removing all
// |'*'| characters.
//
//

LEETCODE_BEGIN_RESOLVING(3170, LexicographicallyMinimumStringAfterRemovingStars,
                         Solution);

class Solution {
public:
  string clearStars(string s) {
    int                                               n = s.size();
    priority_queue<char, vector<char>, greater<char>> pq;
    unordered_map<char, vector<int>>                  m;
    vector<bool>                                      v(n, true);
    for (int i = 0; i < n; ++i) {
      if (s[i] == '*') {
        char tmp = pq.top();
        pq.pop();
        int last = m[tmp].back();
        m[tmp].pop_back();
        v[i]    = false;
        v[last] = false;
      } else {
        pq.push(s[i]);
        m[s[i]].push_back(i);
      }
    }
    string res;
    for (int i = 0; i < n; ++i) {
      if (v[i]) {
        res += s[i];
      }
    }
    return res;
  }
};

LEETCODE_END_RESOLVING(Solution);

